const src = $input.first().json;
const body = src.body ?? src;

const exterior = Array.isArray(body.exterior_images) ? body.exterior_images.filter(Boolean) : [];
const interior = Array.isArray(body.interior_images) ? body.interior_images.filter(Boolean) : [];

if (!body.car_name) {
  throw new Error('car_name is required');
}

if (exterior.length === 0) {
  throw new Error('exterior_images is required');
}

if (interior.length === 0) {
  throw new Error('interior_images is required');
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.wf003Submissions) {
  staticData.wf003Submissions = {};
}

const submissionId = body.run_id || `wf003_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

const count = interior.length;
let interiorGroups = [];
if (count <= 3) {
  interiorGroups = [interior];
} else if (count === 4) {
  interiorGroups = [interior.slice(0, 2), interior.slice(2, 4)];
} else {
  interiorGroups = [interior.slice(0, 3), interior.slice(3, 5)];
}

const expectedTasks = exterior.length + interiorGroups.length;

staticData.wf003Submissions[submissionId] = {
  submissionId,
  run_id: body.run_id || submissionId,
  workflow_code: body.workflow_code || 'WF-003',
  client_request_id: body.client_request_id || '',
  callback_url: body.callback_url || '',
  callback_token: body.callback_token || '',
  car_name: body.car_name,
  logo: body.logo || '',
  token: body.token || '',
  source: body.source || '',
  submitted_at: body.submitted_at || new Date().toISOString(),
  formMode: src.executionMode === 'test' ? 'test' : 'production',
  expectedTasks,
  finalized: false,
  createdAt: new Date().toISOString(),
  tasks: {}
};

return [{
  json: {
    submissionId,
    run_id: body.run_id || submissionId,
    workflow_code: body.workflow_code || 'WF-003',
    client_request_id: body.client_request_id || '',
    callback_url: body.callback_url || '',
    callback_token: body.callback_token || '',
    car_name: body.car_name,
    logo: body.logo || '',
    token: body.token || '',
    source: body.source || '',
    submitted_at: body.submitted_at || new Date().toISOString(),
    exterior_images: exterior,
    interior_images: interior,
    interior_groups: interiorGroups,
    expectedTasks
  }
}];

const input = $input.first().json;
const tasks = [];

(input.exterior_images || []).forEach((url, index) => {
  tasks.push({
    json: {
      submissionId: input.submissionId,
      run_id: input.run_id,
      workflow_code: input.workflow_code,
      client_request_id: input.client_request_id,
      callback_url: input.callback_url,
      callback_token: input.callback_token,
      car_name: input.car_name,
      logo: input.logo,
      expectedTasks: input.expectedTasks,
      type: 'exterior',
      index: index + 1,
      imageUrl: url
    }
  });
});

(input.interior_groups || []).forEach((group, index) => {
  tasks.push({
    json: {
      submissionId: input.submissionId,
      run_id: input.run_id,
      workflow_code: input.workflow_code,
      client_request_id: input.client_request_id,
      callback_url: input.callback_url,
      callback_token: input.callback_token,
      car_name: input.car_name,
      logo: input.logo,
      expectedTasks: input.expectedTasks,
      type: 'interior',
      groupIndex: index + 1,
      imageUrls: group
    }
  });
});

return tasks;

const item = $json;
const callbackUrl = 'https://n8n.deepsix.store/webhook/wf003-kie-callback';

if (item.type === 'exterior') {
  return [{
    json: {
      submissionId: item.submissionId,
      type: item.type,
      index: item.index,
      imageUrl: item.imageUrl,
      requestBody: {
        model: 'nano-banana-2',
        callBackUrl: callbackUrl,
        input: {
          prompt: 'Generate one output image for each uploaded car exterior reference image. If multiple exterior reference images are provided, every single uploaded exterior image must be processed, and none of them can be skipped or omitted. Maintain a strict one-to-one mapping: one reference image = one generated image. Keep the car body completely unchanged in each image, including body shape, proportions, paint color, trim, wheels, headlights, taillights, windows, mirrors, and all exterior design details. Do not alter the vehicle appearance in any way. Change the scene to a premium pure white luxury automotive showroom with a seamless curved white backdrop, polished white reflective floor, subtle architectural layering, soft ambient reflections, hidden linear ceiling lights, diffused studio lighting, and a clean high-end exhibition atmosphere. The showroom should feel elegant, modern, minimal, premium, and suitable for commercial car advertising, while still keeping the background clean and not distracting from the car, do not alter the style of the product logo. Add the logo from the second reference image to the license plate area. Also add the same logo in the top-left corner of each generated image. Do not generate multiple angles from one reference. Generate exactly one result for each uploaded reference image. Preserve the original viewing angle and composition of each reference image. Photorealistic, professional automotive photography, ultra-detailed, premium commercial quality. Output size: 1024x1024.',
          image_input: [item.imageUrl, item.logo],
          aspect_ratio: '1:1',
          resolution: '1K',
          output_format: 'jpg'
        }
      }
    }
  }];
}

return [{
  json: {
    submissionId: item.submissionId,
    type: item.type,
    groupIndex: item.groupIndex,
    imageUrls: item.imageUrls,
    requestBody: {
      model: 'nano-banana-2',
      callBackUrl: callbackUrl,
      input: {
        prompt: '严格使用我上传的内饰原图拼图。不要改变原图的角度，不要生成新画面，不要把一张图裁成多个局部特写。每个面板必须对应一张不同的上传原图。每张图只能使用一次，不能重复，所有上传图片都必须使用。上传1-3张时生成1张拼图；上传4张时生成2张拼图，按2+2分组；上传5张时生成2张拼图，按3+2分组。使用干净整齐的网格或并排布局，面板清晰分隔，保持原图完整清晰，不拉伸、不重叠。专业汽车内饰拼图风格。输出尺寸：1024×1024。',
        image_input: item.imageUrls,
        aspect_ratio: '1:1',
        resolution: '1K',
        output_format: 'jpg'
      }
    }
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.wf003Submissions) {
  staticData.wf003Submissions = {};
}

const requestMeta = $('Prepare Kie Task Payload').item.json;
const createResp = $json || {};
const taskId = createResp?.data?.taskId || null;

if (!taskId) {
  throw new Error('Kie createTask returned no taskId');
}

const submission = staticData.wf003Submissions[requestMeta.submissionId];
if (!submission) {
  throw new Error(`Submission not found: ${requestMeta.submissionId}`);
}

submission.tasks[taskId] = requestMeta.type === 'exterior'
  ? {
      type: 'exterior',
      index: requestMeta.index,
      imageUrl: requestMeta.imageUrl,
      taskId,
      state: 'submitted',
      resultUrl: null,
      createdAt: new Date().toISOString()
    }
  : {
      type: 'interior',
      groupIndex: requestMeta.groupIndex,
      imageUrls: requestMeta.imageUrls,
      taskId,
      state: 'submitted',
      resultUrl: null,
      createdAt: new Date().toISOString()
    };

return [{
  json: {
    ok: true,
    submissionId: requestMeta.submissionId,
    taskId,
    type: requestMeta.type,
    index: requestMeta.index || null,
    groupIndex: requestMeta.groupIndex || null
  }
}];

const source = $('Normalize Submission').first().json;
return [{
  json: {
    ok: true,
    message: 'Tasks submitted to Kie. Waiting for callbacks.',
    submissionId: source.submissionId,
    expectedTasks: source.expectedTasks,
    exteriorCount: (source.exterior_images || []).length,
    interiorCount: (source.interior_images || []).length
  }
}];

const src = $input.first().json;
const body = src.body ?? src;
const data = body.data || {};

let resultJson = {};
try {
  if (typeof data.resultJson === 'string') {
    resultJson = JSON.parse(data.resultJson);
  } else if (data.resultJson && typeof data.resultJson === 'object') {
    resultJson = data.resultJson;
  }
} catch (error) {
  resultJson = {};
}

const resultUrls = Array.isArray(resultJson.resultUrls) ? resultJson.resultUrls : [];
const resultUrl = resultUrls[0] || body.resultUrl || data.resultUrl || null;
const taskId = data.taskId || body.taskId || body.id || null;
const rawState = String(data.state || body.state || '').toLowerCase();
const failCode = data.failCode || body.failCode || null;
const failMsg = data.failMsg || body.failMsg || body.msg || null;

if (!taskId) {
  throw new Error('Callback contains no taskId');
}

let state = rawState || 'unknown';
if (resultUrl) {
  state = 'success';
} else if (['failed', 'fail', 'error'].includes(state)) {
  state = 'failed';
}

return [{
  json: {
    taskId,
    state,
    rawState,
    resultUrl,
    failCode,
    failMsg,
    body
  }
}];

const staticData = $getWorkflowStaticData('global');
const store = staticData.wf003Submissions || {};
const callback = $json;

let submissionId = null;
let submission = null;
let task = null;

for (const [key, value] of Object.entries(store)) {
  if (value?.tasks?.[callback.taskId]) {
    submissionId = key;
    submission = value;
    task = value.tasks[callback.taskId];
    break;
  }
}

if (!submission || !task) {
  return [{
    json: {
      ok: false,
      accepted: true,
      reason: 'task_not_found',
      taskId: callback.taskId,
      isComplete: false
    }
  }];
}

submission.tasks[callback.taskId] = {
  ...task,
  state: callback.state,
  rawState: callback.rawState,
  resultUrl: callback.resultUrl || task.resultUrl || null,
  failCode: callback.failCode || null,
  failMsg: callback.failMsg || null,
  lastCallbackAt: new Date().toISOString(),
  callbackPayload: callback.body
};

const tasks = Object.values(submission.tasks);
const resolvedCount = tasks.filter(t => ['success', 'failed', 'error'].includes(t.state) || !!t.resultUrl).length;
const successCount = tasks.filter(t => t.state === 'success' && !!t.resultUrl).length;
const failedCount = tasks.filter(t => ['failed', 'error'].includes(t.state)).length;
const isComplete = resolvedCount >= submission.expectedTasks && !submission.finalized;

return [{
  json: {
    ok: true,
    accepted: true,
    submissionId,
    taskId: callback.taskId,
    taskType: task.type,
    state: callback.state,
    resultUrl: callback.resultUrl,
    failCode: callback.failCode || null,
    failMsg: callback.failMsg || null,
    expectedTasks: submission.expectedTasks,
    resolvedCount,
    successCount,
    failedCount,
    isComplete
  }
}];

const staticData = $getWorkflowStaticData('global');
const submissionId = $('Update Submission State').first().json.submissionId;
const submission = staticData.wf003Submissions?.[submissionId];

if (!submission) {
  throw new Error(`Submission not found: ${submissionId}`);
}

const tasks = Object.values(submission.tasks || {});

const exteriorImages = tasks
  .filter(t => t.type === 'exterior' && t.state === 'success' && t.resultUrl)
  .sort((a, b) => (a.index || 0) - (b.index || 0))
  .map((t, i) => ({
    originalIndex: t.index,
    imageUrl: t.resultUrl,
    fileName: `exterior_${i + 1}.jpg`
  }));

const interiorImages = tasks
  .filter(t => t.type === 'interior' && t.state === 'success' && t.resultUrl)
  .sort((a, b) => (a.groupIndex || 0) - (b.groupIndex || 0))
  .map((t, i) => ({
    groupIndex: t.groupIndex,
    imageUrl: t.resultUrl,
    fileName: `interior_${i + 1}.jpg`
  }));

const failedTasks = tasks
  .filter(t => ['failed', 'error'].includes(t.state))
  .map(t => ({
    type: t.type,
    index: t.index || t.groupIndex || null,
    taskId: t.taskId,
    failCode: t.failCode || null,
    failMsg: t.failMsg || null
  }));

submission.finalized = true;
submission.finalizedAt = new Date().toISOString();

return [{
  json: {
    submissionId,
    run_id: submission.run_id || submissionId,
    workflow_code: submission.workflow_code || 'WF-003',
    client_request_id: submission.client_request_id || '',
    callback_url: submission.callback_url || '',
    callback_token: submission.callback_token || '',
    car_name: submission.car_name,
    exteriorImages,
    interiorImages,
    totalExterior: exteriorImages.length,
    totalInterior: interiorImages.length,
    successCount: tasks.filter(t => t.state === 'success' && t.resultUrl).length,
    failedCount: failedTasks.length,
    failedTasks
  }
}];

const input = $input.first().json || {};
const exteriorImages = Array.isArray(input.exteriorImages) ? input.exteriorImages : [];
const interiorImages = Array.isArray(input.interiorImages) ? input.interiorImages : [];
const groupName = `二手车图片_${Date.now()}`;
const vehicleId = `car_${Date.now()}`;
const items = [];

exteriorImages.forEach((item, index) => {
  const url = item.imageUrl || '';
  if (!url) return;
  items.push({
    json: {
      submissionId: input.submissionId,
      groupName,
      vehicleId,
      category: '外观图',
      order: index + 1,
      sourceUrl: url,
      fileName: `exterior_${index + 1}.jpg`
    }
  });
});

interiorImages.forEach((item, index) => {
  const url = item.imageUrl || '';
  if (!url) return;
  items.push({
    json: {
      submissionId: input.submissionId,
      groupName,
      vehicleId,
      category: '内饰图',
      order: index + 1,
      sourceUrl: url,
      fileName: `interior_${index + 1}.jpg`
    }
  });
});

return items;

return [{
  json: {
    submissionId: $('Loop Upload Items').item.json.submissionId,
    groupName: $('Loop Upload Items').item.json.groupName,
    vehicleId: $('Loop Upload Items').item.json.vehicleId,
    category: $('Loop Upload Items').item.json.category,
    order: $('Loop Upload Items').item.json.order,
    fileName: $('Loop Upload Items').item.json.fileName,
    fileToken: $json.data?.file_token || $json.file_token || ''
  }
}];

const items = $input.all();
const result = {
  submissionId: items[0]?.json?.submissionId || '',
  groupName: items[0]?.json?.groupName || `二手车图片_${Date.now()}`,
  vehicleId: items[0]?.json?.vehicleId || `car_${Date.now()}`,
  exteriorAttachments: [],
  interiorAttachments: []
};

for (const item of items) {
  const token = item.json.fileToken;
  if (!token) continue;

  const attachment = { file_token: token };

  if (item.json.category === '外观图') {
    result.exteriorAttachments.push(attachment);
  } else if (item.json.category === '内饰图') {
    result.interiorAttachments.push(attachment);
  }
}

return [{ json: result }];

